#!/usr/bin/env bash
# Builds index.html (a full web page for GitHub Pages) from game.html (the
# Claude artifact source, which has no <html>/<head> wrapper of its own).
set -euo pipefail
cd "$(dirname "$0")"
python3 - <<'PY'
src = open('game.html', encoding='utf-8').read()
cut = src.index('<div class="app">')
head, body = src[:cut].strip(), src[cut:].strip()
page = f'''<!doctype html>
<!-- Generated by build.sh from game.html. Edit game.html, then run ./build.sh. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#121418">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="mobile-web-app-capable" content="yes">
<meta name="description" content="A black-and-gold football coin pusher: time the drop, push coins into the end zone, and collect player cards and Super Bowl rings.">
<style>:root {{ padding-top: env(safe-area-inset-top, 0px); padding-bottom: env(safe-area-inset-bottom, 0px); }}</style>
{head}
</head>
<body>
{body}
</body>
</html>
'''
open('index.html', 'w', encoding='utf-8').write(page)
PY
echo "Wrote index.html"
